import com.wolinski.shop.money.Money;
import com.wolinski.shop.platform.ShopProblem;

/** A percentage discount, as whole basis points (ADR 8). */
final class Discount {

    private static final long WHOLE_PERCENT_MAX = 100;
    private static final long BASIS_POINTS_PER_PERCENT = 100;
    private static final long BASIS_POINTS_MAX = WHOLE_PERCENT_MAX * BASIS_POINTS_PER_PERCENT;
    private static final long BASIS_POINTS_DIVISOR = 10_000;

    private Discount() {
    }

    /**
     * Converts text such as "12.5" or "12.50" to basis points (1250). Accepts up to two decimal places.
     */
    static long basisPoints(String text) {
        String s = null == text ? "" : text.trim();
        int dot = s.indexOf('.');
        String whole = dot < 0 ? s : s.substring(0, dot);
        String fraction = dot < 0 ? "" : s.substring(dot + 1);

        if (whole.isEmpty() || !allDigits(whole)
                || (dot >= 0 && (fraction.isEmpty() || fraction.length() > 2 || !allDigits(fraction)))) {
            throw new ShopProblem("INVALID_PERCENT", "Percent must be a number like 12.5, with at most two decimals: " + text);
        }
        if (whole.length() > 3) {
            throw outOfRange(text);
        }

        long wholePart = Long.parseLong(whole);
        long fractionPart = 0;
        if (fraction.length() == 1) {
            fractionPart = Long.parseLong(fraction) * 10;
        } else if (fraction.length() == 2) {
            fractionPart = Long.parseLong(fraction);
        }

        long basisPoints = wholePart * BASIS_POINTS_PER_PERCENT + fractionPart;
        if (basisPoints > BASIS_POINTS_MAX) {
            throw outOfRange(text);
        }
        return basisPoints;
    }

    /** The discount on a total, rounded half up to a whole minor unit. Totals are not negative. */
    static Money of(Money total, long basisPoints) {
        long discount = (total.minorUnits() * basisPoints + BASIS_POINTS_DIVISOR / 2) / BASIS_POINTS_DIVISOR;
        return new Money(discount, total.currency());
    }

    private static boolean allDigits(String s) {
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c < '0' || c > '9') {
                return false;
            }
        }
        return true;
    }

    private static ShopProblem outOfRange(String text) {
        return new ShopProblem("PERCENT_OUT_OF_RANGE", "Percent must be between 0 and 100: " + text);
    }
}
}

