import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertThrows;

import com.wolinski.shop.money.Money;
import com.wolinski.shop.platform.ShopProblem;
import org.junit.jupiter.api.Test;

class DiscountTest {

    @Test
    void textBecomesBasisPoints() {
        assertEquals(1250, Discount.basisPoints("12.5"));
        assertEquals(1250, Discount.basisPoints("12.50"));
        assertEquals(1200, Discount.basisPoints("12"));
        assertEquals(5, Discount.basisPoints("0.05"));
        assertEquals(10000, Discount.basisPoints("100"));
        assertEquals(0, Discount.basisPoints("0"));
        assertEquals(1250, Discount.basisPoints(" 12.5 "));
    }

    @Test
    void malformedTextIsRefused() {
        for (String text : new String[] {null, "", " ", "abc", "12,5", "-1", "+5", "1e2", ".5", "12.", "12.555", "1.2.3", "1 2"}) {
            ShopProblem problem = assertThrows(ShopProblem.class, () -> Discount.basisPoints(text), text);
            assertEquals("INVALID_PERCENT", problem.code());
        }
    }

    @Test
    void outOfRangeIsRefused() {
        for (String text : new String[] {"100.01", "101", "999", "99999999999999999999"}) {
            ShopProblem problem = assertThrows(ShopProblem.class, () -> Discount.basisPoints(text), text);
            assertEquals("PERCENT_OUT_OF_RANGE", problem.code());
        }
    }

    @Test
    void halfPercentOfOneZlotyIsOneGrosz() {
        assertEquals(Money.pln(1), Discount.of(Money.pln(100), Discount.basisPoints("0.5")));
    }

    @Test
    void discountRoundsHalfUp() {
        // 12.5% of 0.10 PLN = 0.0125 PLN -> 0.01
        assertEquals(Money.pln(1), Discount.of(Money.pln(10), Discount.basisPoints("12.5")));
        // 12.5% of 0.20 PLN = 0.025 PLN -> 0.03 (half up)
        assertEquals(Money.pln(3), Discount.of(Money.pln(20), Discount.basisPoints("12.5")));
        // 12.5% of 0.04 PLN = 0.005 PLN -> 0.01 (half up)
        assertEquals(Money.pln(1), Discount.of(Money.pln(4), Discount.basisPoints("12.5")));
        // 12.5% of 0.03 PLN = 0.00375 PLN -> 0
        assertEquals(Money.pln(0), Discount.of(Money.pln(3), Discount.basisPoints("12.5")));
    }
}
}

