    void applyDiscountLowersTheTotalByTheRoundedDiscount() {
        OrderService service = new OrderService(new OrderRepository());
        String id = service.place("c-1", Money.pln(100), Instant.parse("2026-10-01T10:00:00Z"));

        service.applyDiscount(id, "0.5");

        assertEquals(Money.pln(99), service.summary(id).total());
    }

