    void applyDiscountOnAnOrderThatDoesNotExistFails() {
        OrderService service = new OrderService(new OrderRepository());

        org.junit.jupiter.api.Assertions.assertThrows(
                java.util.NoSuchElementException.class, () -> service.applyDiscount("missing", "10"));
    }
}
}

